use vstd::prelude::*;

verus! {

    fn rolling_max(numbers: Vec<i32>) -> (result: Vec<i32>)
        ensures
            result.len() == numbers.len(),
            result.as_seq() == rolling_max_seq(numbers.as_seq())
    {
        let mut result: Vec<i32> = Vec::new();
        let n: usize = numbers.len();
        let mut i: usize = 0;
        while i < n
            invariant
                i <= n,
                result.len() == i,
                // result contains the rolling max of the first i elements
                result.as_seq() == rolling_max_seq(numbers.as_seq().slice(0, i)),
            decreases n - i
        {
            let cur = numbers.index(i);
            if i == 0 {
                // first element, rolling max is just numbers[0]
                result.push(cur);
            } else {
                // get the previous rolling max
                let prev_max = result.index(i - 1);
                // push the greater of prev_max and cur
                if prev_max < cur {
                    result.push(cur);
                } else {
                    result.push(prev_max);
                }
            }
            i = i + 1;
        }
        result
    }

}

